R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-5';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(160, 'the-red-soap-dish', 'The red soap dish', 'The old red soap dish carries the grandfather’s gift and the speaker’s sense of not fitting into a changed world. Show the humble object in a contemporary washroom without turning it into a luxury product advertisement.', 'Horizontal 3:2 restrained gouache still life. One small plain red plastic oval soap dish with softened corners sits toward lower left on a clean muted grey stone shower ledge. A partly used cream-coloured rectangular soap bar rests inside, rounded by use, modest wet contact, no lettering. The plastic is slightly dulled where handled but not broken, filthy or quaintly distressed. Far upper right, the cropped out-of-focus bottom of one plain tall pump bottle just enters the frame, distant enough to leave most ledge empty. Coherent soap-dish rim, gravity and soft side light, ordinary tiled wall. Red dish is the emotional anchor, not a glamorous merchandise shot. No people, hands, packaging labels, brand symbols, sparkles or excessive droplets.'), (150, 'listening-under-the-leaves', 'Listening under the leaves', 'The poem imagines trees singing where the mechanical world hears nothing. A view from beneath an uneven canopy offers the reader the pause of listening without faces in trees or visible musical symbols.', 'Horizontal 3:2 charcoal and transparent olive-green watercolor on warm ivory paper. Look upward from beneath an ordinary leafy tree: one irregular dark branch enters from upper left and divides naturally, overlapping clusters of leaves partly hide finer twigs. Leaves have unequal density, some turned edge-on, some merged into soft wash; a few selective charcoal leaf contours, not every leaf outlined. Broad irregular pale sky opening at center-right and lower frame, no horizon or house. Gentle daylight filters through leaves without rays, halos or decorative glitter. Quiet varied greens, charcoal greys and paper breathing space. No human figures, birds, flowers, faces hidden in bark, words, notes or musical symbols. A lived moment of listening, not a botanical diagram.'), (154, 'petals-below-the-open-diary', 'Petals below the open diary', 'The poem returns to dry petals slipping from diary pages. Frame the small aftermath at the edge of a table, letting absence remain unpictured and avoiding a fabricated face or decorative love letter.', 'Horizontal 3:2 dry pastel with fine pencil, quiet close still life. A partly open plain old diary rests near the far left edge of a simple muted brown tabletop, its upper portion cropped out of frame, no readable writing. Several unequal dry rose petals lie loosely on the floor immediately below the table edge; one petal is partly hidden behind the table leg, no elegant spiral arrangement, none floating. View obliquely downward with coherent table thickness and one straight supporting leg, restrained ordinary side daylight and soft contact shadows. Subdued dusty rose, warm paper, grey-brown floor; most right half empty floor. Diary pages bend at binding, no photographs, pen, cup, lamp, fresh roses, person, ornate ornaments or lettering. Suggest the small accidental aftermath of opening the diary, not a styled stationery flat lay.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-05/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal 3:2 literary artwork for Kabita Live Issue5. Human Natural in Poetic Natural mode. Preserve the selected expressive medium; a painted interpretation, never documentary evidence.\nEmotional anchor: {reason}\nScene and medium: {scene}\nAnti-optimization checks: avoid staged object display, equal detail everywhere, mechanically repeated shapes, theatrical lighting and cosmetic distress. Material contact, geometry and illumination must make sense. Preserve quiet negative space and emotional ambiguity. No identifiable real people, portraits, readable text, signature, logos or watermark. No people, portraits or documentary location claims. Opaque ivory-paper background.\nPoem {d["title"]} by {d["author"]}; source read fully, use as context only, never render the words:\n{d["text"]}\n'
