 items.append(dict(id=ident,edition=5,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-5/{ident}/v1.png',attempts=[],medium_label={160:'gouache',150:'charcoal and watercolor',154:'dry pastel and pencil'}[pid],independent=False))
